<template><div class="page"><div class="page-header"><div><h1 class="page-title">知识库检索测试</h1><p class="page-description">查看RAG实际召回的原文片段、来源和相似度。</p></div></div><div class="card card-body"><el-form :model="form" label-position="top"><div class="form-grid"><el-form-item label="课程"><el-select v-model="form.course_id" style="width:100%"><el-option v-for="c in store.courses" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="指定文件（可选）"><el-select v-model="form.file_id" clearable style="width:100%"><el-option v-for="f in files" :key="f.id" :label="f.original_name" :value="f.id"/></el-select></el-form-item><el-form-item label="Top K"><el-input-number v-model="form.top_k" :min="1" :max="20"/></el-form-item><el-form-item label="相似度阈值"><el-slider v-model="form.similarity_threshold" :min="0" :max="1" :step="0.05" show-input/></el-form-item><el-form-item label="检索问题" class="full"><el-input v-model="form.query" type="textarea" :rows="3" placeholder="例如：Python函数如何定义？"/></el-form-item></div><el-button type="primary" :loading="loading" @click="search">开始检索</el-button></el-form></div><div v-if="searched" style="margin-top:18px"><PageState :empty="!results.length" empty-text="没有找到达到相似度阈值的文本块，请降低阈值或更换问题。"><article v-for="r in results" :key="r.chunk_id" class="result-card card"><div class="result-meta"><el-tag>相似度 {{(r.similarity*100).toFixed(1)}}%</el-tag><span>文本块 #{{r.chunk_id}}</span><span>页码 {{r.page_number||'-'}}</span></div><p>{{r.content}}</p></article></PageState></div></div></template><script setup>import{reactive,ref,watch,onMounted}from'vue';import{ElMessage}from'element-plus';import{knowledgeApi}from'../../api';import{useAppStore}from'../../stores/app';import PageState from'../../components/PageState.vue';const store=useAppStore(),files=ref([]),results=ref([]),loading=ref(false),searched=ref(false),form=reactive({course_id:'',file_id:'',query:'',top_k:5,similarity_threshold:.25});watch(()=>form.course_id,async id=>{if(id){const d=await knowledgeApi.files({course:id,page_size:100,status:'SUCCESS'});files.value=d.items}else files.value=[]});const search=async()=>{if(!form.course_id||!form.query.trim())return ElMessage.warning('请选择课程并输入检索问题');loading.value=true;try{results.value=await knowledgeApi.search(form);searched.value=true}finally{loading.value=false}};onMounted(store.loadCourses)</script><style scoped>.result-card{padding:18px;margin-bottom:12px}.result-meta{display:flex;align-items:center;gap:14px;color:var(--text-secondary);font-size:12px}.result-card p{white-space:pre-wrap;line-height:1.8}</style>
